css:
.print-format { font-size: 10.5pt; line-height: 1.45; }
.sla-letter { padding-right: 8px; }
.sla-letter h3 { text-align: center; text-decoration: underline; font-size: 12pt; margin: 6px 0 16px; }
.sla-letter table.sla-meta { width: 100%; margin-bottom: 14px; }
.sla-letter table.sla-meta td { padding: 2px 4px; vertical-align: top; border: none; }
.sla-letter table.sla-meta td.lbl { width: 32%; font-weight: 700; }
.sla-letter h4 { font-size: 10.5pt; font-weight: 700; margin: 14px 0 4px; }
.sla-letter .box { border: 1px solid #333; padding: 6px 8px; white-space: pre-wrap; }
.sla-letter table.sla-sign { width: 100%; margin-top: 36px; page-break-inside: avoid; }
.sla-letter table.sla-sign td { width: 50%; padding-top: 34px; vertical-align: top; border: none; }
